//! Banco de preguntas del modo tablero.

use bevy::prelude::*;
use rand::Rng;

use crate::i18n; // Selecciona el banco de preguntas según el idioma activo.

/// Dificultad de las preguntas.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Difficulty {
    Easy,
    Medium,
    Hard,
}

impl Difficulty {
    /// Todas las dificultades en orden creciente.
    pub fn all() -> [Difficulty; 3] {
        [Difficulty::Easy, Difficulty::Medium, Difficulty::Hard]
    }

    /// Nombre legible.
    pub fn name(self) -> &'static str {
        match self {
            Difficulty::Easy => "Fácil",
            Difficulty::Medium => "Media",
            Difficulty::Hard => "Difícil",
        }
    }
}

/// Categorías temáticas del tablero.
///
/// Las 6 primeras son los "Estrellitas de color" del tablero; `Taboo` es la
/// categoría del reto final (la 7ª Estrellita) y de las casillas especiales.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Category {
    Math,
    History,
    Cs,
    Geography,
    Science,
    Art,
    Taboo,
}

impl Category {
    /// Solo las 6 categorías de color (las Estrellitas del tablero).
    pub fn colored() -> [Category; 6] {
        [
            Category::Math,
            Category::History,
            Category::Cs,
            Category::Geography,
            Category::Science,
            Category::Art,
        ]
    }

    /// Nombre legible.
    pub fn name(self) -> &'static str {
        match self {
            Category::Math => "Matemáticas",
            Category::History => "Historia",
            Category::Cs => "Informática",
            Category::Geography => "Geografía",
            Category::Science => "Ciencia y Naturaleza",
            Category::Art => "Arte y Literatura",
            Category::Taboo => "Tabú",
        }
    }

    /// Color distintivo de la categoría (casillas del tablero).
    ///
    /// Sigue los colores del Trivial Pursuit clásico: azul = Geografía,
    /// amarillo = Historia, verde = Ciencia y Naturaleza, púrpura = Arte y
    /// Literatura. Rosa y naranja (Entretenimiento y Deportes y Ocio en el
    /// original) los usan aquí las asignaturas propias del colegio:
    /// Informática y Matemáticas.
    pub fn color(self) -> Color {
        match self {
            Category::Math => Color::srgb(0.95, 0.55, 0.15),
            Category::History => Color::srgb(0.92, 0.80, 0.25),
            Category::Cs => Color::srgb(0.95, 0.45, 0.55),
            Category::Geography => Color::srgb(0.30, 0.50, 0.92),
            Category::Science => Color::srgb(0.30, 0.68, 0.35),
            Category::Art => Color::srgb(0.60, 0.35, 0.80),
            // El Tabú usa un color dorado propio.
            Category::Taboo => Color::srgb(0.88, 0.75, 0.25),
        }
    }
}

/// Una pregunta del tablero.
///
/// Puede ser **cerrada** (4 opciones, la correcta es `correct`) o **abierta**
/// (`open` = true, sin opciones: se escribe la respuesta y se compara con
/// `answer` de forma tolerante). Como el Trivial real, no todas las
/// preguntas ofrecen respuestas.
#[derive(Clone, Copy)]
pub struct Question {
    pub category: Category,
    pub difficulty: Difficulty,
    pub text: &'static str,
    /// `true` = pregunta abierta (se escribe la respuesta, sin opciones).
    pub open: bool,
    /// Opciones de las preguntas cerradas (ignoradas si `open`).
    pub options: [&'static str; 4],
    /// Índice de la opción correcta (ignorado si `open`).
    pub correct: usize,
    /// Respuesta correcta de las preguntas abiertas (ignorada si no `open`).
    pub answer: &'static str,
}

impl Question {
    /// Baraja las opciones y devuelve la pregunta con el índice correcto
    /// actualizado. Así la respuesta correcta nunca está siempre en la misma
    /// letra (A, B, C o D). Las preguntas abiertas se devuelven tal cual.
    pub fn shuffled(mut self) -> Self {
        if self.open {
            return self;
        }
        use rand::seq::SliceRandom;

        let mut order = [0usize, 1, 2, 3];
        order.shuffle(&mut rand::thread_rng());
        let old = self.options;
        for (slot, &from) in order.iter().enumerate() {
            self.options[slot] = old[from];
        }
        self.correct = order.iter().position(|&i| i == self.correct).unwrap();
        self
    }
}

/// Normaliza una respuesta para compararla de forma tolerante: minúsculas,
/// sin acentos ni espacios extra. Así "PARÍS " y "paris" cuentan como
/// respuestas iguales.
pub fn normalize_answer(input: &str) -> String {
    let mut out = String::with_capacity(input.len());
    for ch in input.trim().chars() {
        for lower in ch.to_lowercase() {
            out.push(match lower {
                'á' => 'a',
                'é' => 'e',
                'í' => 'i',
                'ó' => 'o',
                'ú' => 'u',
                'ü' => 'u',
                'ñ' => 'n',
                other => other,
            });
        }
    }
    // Colapsa espacios múltiples.
    let mut collapsed = String::with_capacity(out.len());
    let mut prev_space = false;
    for ch in out.chars() {
        if ch == ' ' {
            if !prev_space {
                collapsed.push(ch);
            }
            prev_space = true;
        } else {
            collapsed.push(ch);
            prev_space = false;
        }
    }
    collapsed.trim().to_string()
}

/// Macro para declarar preguntas cerradas de forma compacta.
macro_rules! q {
    ($cat:expr, $diff:expr, $text:expr, $correct:expr, [$a:expr, $b:expr, $c:expr, $d:expr]) => {
        Question {
            category: $cat,
            difficulty: $diff,
            text: $text,
            open: false,
            options: [$a, $b, $c, $d],
            correct: $correct,
            answer: "",
        }
    };
}

/// Macro para declarar preguntas abiertas (sin opciones): se escribe la
/// respuesta y se compara con `$answer` de forma tolerante.
macro_rules! q_open {
    ($cat:expr, $diff:expr, $text:expr, $answer:expr) => {
        Question {
            category: $cat,
            difficulty: $diff,
            text: $text,
            open: true,
            options: ["", "", "", ""],
            correct: 0,
            answer: $answer,
        }
    };
}

// Las macros también se usan en los bancos traducidos (bank_en.rs/bank_fr.rs).
pub(crate) use q;
pub(crate) use q_open;

