/// Elige al azar de un subconjunto del banco activo (según el idioma), por
/// categoría y dificultad, y opcionalmente solo cerradas o cualquier tipo.
fn random_from(category: Category, difficulty: Difficulty, only_closed: bool) -> Question {
    let pool: Vec<&Question> = active_bank()
        .iter()
        .filter(|q| q.category == category && q.difficulty == difficulty)
        .filter(|q| !only_closed || !q.open)
        .collect();
    let index = rand::thread_rng().gen_range(0..pool.len());
    pool[index].shuffled()
}

/// Banco de preguntas del tablero según el idioma activo.
///
/// Los bancos traducidos (EN/FR) se generan en `bank_en.rs` y `bank_fr.rs` y
/// contienen exactamente las mismas preguntas traducidas. El español es el
/// banco original de `questions.rs`.
pub fn active_bank() -> &'static [Question] {
    match crate::i18n::language() {
        crate::i18n::Language::En => super::bank_en::questions_en(),
        crate::i18n::Language::Fr => super::bank_fr::questions_fr(),
        crate::i18n::Language::Es => QUESTIONS,
    }
}

/// Devuelve una pregunta al azar de la categoría y dificultad indicadas,
/// con las opciones ya barajadas. Puede ser cerrada o abierta (como el
/// Trivial real, no todas ofrecen respuestas).
pub fn random_question(category: Category, difficulty: Difficulty) -> Question {
    random_from(category, difficulty, false)
}

/// Devuelve una pregunta **cerrada** al azar (con 4 opciones). El reto final
/// del centro siempre es cerrado (más determinista y fiel al Trivial clásico)
/// y los tests la usan para que el flujo de opciones sea determinista.
pub fn random_closed_question(category: Category, difficulty: Difficulty) -> Question {
    random_from(category, difficulty, true)
}

// =========================================================================
// Tarjetas Tabú (Fase 9)
// =========================================================================
//
// El Tabú real no es una adivinanza con opciones: se muestra una tarjeta con
// la **palabra objetivo** arriba y **5 palabras prohibidas** debajo. Un
// jugador describe la palabra a sus compañeros sin decirla ni decir ninguna
// de las prohibidas; si la aciertan antes de que se acabe el tiempo, suma el
// punto. Cada banco tiene las variantes en español, inglés y francés.

/// Tarjeta Tabú: palabra objetivo + 5 palabras prohibidas + pista.
#[derive(Clone, Copy)]
pub struct TabooCard {
    /// Palabra que hay que adivinar (se describe sin decirla).
    pub target: &'static str,
    /// Palabras que NO se pueden decir al describir.
    pub forbidden: [&'static str; 5],
    /// Pista corta de categoría para orientar al equipo.
    pub hint: &'static str,
}

