/// Devuelve una tarjeta Tabú al azar en el idioma activo.
pub fn random_taboo_card() -> TabooCard {
    let bank = match i18n::language() {
        i18n::Language::En => TABOO_EN,
        i18n::Language::Fr => TABOO_FR,
        i18n::Language::Es => TABOO_ES,
    };
    let index = rand::thread_rng().gen_range(0..bank.len());
    bank[index]
}